SELECT t.customer_id AS customer_id, t.tag_id AS tag_id, t.tag_name AS tag_name, COALESCE(d.tag_group, t.tag_group, '其它') AS tag_group, COALESCE(d.color, 'gray') AS color, COALESCE(d.tag_type, 1) AS tag_type, t.source AS source, t.operator_name AS operator_name, t.create_time AS create_time FROM customer_tag t LEFT JOIN customer_tag_def d ON d.id = t.tag_id AND d.is_deleted = FALSE WHERE t.tenant_code = #{tenantCode} AND t.is_deleted = FALSE AND t.customer_id IN
#{id}
ORDER BY COALESCE(d.sort_no, 100), t.tag_name

SELECT DISTINCT t.customer_id
  FROM customer_tag t
 WHERE t.tenant_code = #{tenantCode}
   AND t.is_deleted = FALSE
   AND t.tag_id = #{tagId}
